#include "../../../vendor/md4c-reference/src/md4c.c"
int main(void) {
  const char* inputs[] = {"<![CDATA[x]]>", "<!\xc3\xa9>", "<!\xc3\xa9 long declaration>", "<custom> \t\v\f\n"};
  for (int i=0; i<4; ++i) {
    MD_CTX ctx;
    memset(&ctx,0,sizeof(ctx));
    ctx.text=inputs[i];
    ctx.size=(MD_SIZE)strlen(inputs[i]);
    printf("%d\n",md_is_html_block_start_condition(&ctx,0));
  }
  MD_CTX ctx;
  memset(&ctx,0,sizeof(ctx));
  ctx.text="|---| \t";
  ctx.size=(MD_SIZE)strlen(ctx.text);
  OFF end=0;
  unsigned columns=0;
  int result=md_is_table_underline(&ctx,0,&end,&columns);
  printf("%d %u %u\n",result,end,columns);
  ctx.text="x-->y";ctx.size=(MD_SIZE)strlen(ctx.text);end=0;
  result=md_line_contains(&ctx,0,"-->",3,&end);
  printf("%d %u\n",result,end);
  ctx.text="abcdef";ctx.size=(MD_SIZE)strlen(ctx.text);end=0;
  result=md_line_contains(&ctx,0,"-->",3,&end);
  printf("%d %u\n",result,end);
  return 0;
}
